from sage.all_cmdline import *   # import sage library

_sage_const_400 = Integer(400); _sage_const_350 = Integer(350); _sage_const_0 = Integer(0); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_10 = Integer(10); _sage_const_8 = Integer(8); _sage_const_1000 = Integer(1000); _sage_const_3 = Integer(3); _sage_const_5 = Integer(5); _sage_const_100 = Integer(100); _sage_const_12345 = Integer(12345); _sage_const_6 = Integer(6); _sage_const_0p4407 = RealNumber('0.4407'); _sage_const_0p813 = RealNumber('0.813'); _sage_const_5p4e8 = RealNumber('5.4e8'); _sage_const_1p7 = RealNumber('1.7'); _sage_const_1en30 = RealNumber('1e-30')# ---------------------------------------------------------
# <negative_number_to_sqrt>   x < 0 について  x = -sqrt((-x)^2)^{(R_{>=0})}
#
# 独立経路: 右辺の平方根を、組み込みの sqrt ではなく
# <sqrt_nonnegative_existence_uniqueness> の存在証明と同じ二分法
# （S = {s>=0 | s^2 <= a} の上限）で構成する。
# 左辺は与えた x そのものなので、突き合わせは同語反復にならない。
#
# 反例探索の方針: 主張は x<0 でのみ成立する。x>0 では
#   -sqrt((-x)^2) = -x != x
# となるはずなので、x>0 でも走査して「符号が効いていること」を確認する。
# ---------------------------------------------------------
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if '__file__' in dir() else '.'
load(os.path.join(_dir, '../../_shared/operators.sage'))

RF = RealField(_sage_const_400 )
ITERS = _sage_const_350 

def sqrt_nonneg_bisect(a):
    a = RF(a)
    lo, hi = RF(_sage_const_0 ), RF(_sage_const_1 ) + a
    for _ in range(ITERS):
        mid = (lo + hi) / _sage_const_2 
        if mid * mid <= a:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / _sage_const_2 

NEGS = [RF(v) for v in [
    -_sage_const_1 /_sage_const_10 **_sage_const_8 , -_sage_const_1 /_sage_const_1000 , -_sage_const_1 /_sage_const_2 , -_sage_const_1 , -_sage_const_2 , -_sage_const_3 , -_sage_const_5 , -_sage_const_10 , -_sage_const_100 , -_sage_const_12345 ,
    -_sage_const_10 **_sage_const_6 , -_sage_const_2 *_sage_const_0p4407 , -_sage_const_2 *_sage_const_0p813 , -_sage_const_5p4e8 , -_sage_const_1p7 ,
]]

rep = CheckReport("<negative_number_to_sqrt> x<0 => x = -sqrt((-x)^2)")

for x in NEGS:
    rhs = -sqrt_nonneg_bisect((-x)**_sage_const_2 )
    denom = max(RF(_sage_const_1 ), abs(x))
    rep.close(float(x / denom), float(rhs / denom), "x = -sqrt((-x)^2) @x=%s" % x)

# 仮定 x<0 が効いていること: x>0 では -sqrt((-x)^2) = -x != x
n_broken = _sage_const_0 
POSS = [-v for v in NEGS]
for x in POSS:
    rhs = -sqrt_nonneg_bisect((-x)**_sage_const_2 )
    if abs(rhs - x) > RF(_sage_const_1en30 ) * max(RF(_sage_const_1 ), abs(x)):
        n_broken += _sage_const_1 
rep.truth(n_broken == len(POSS),
          "x>0 では全 %d 例で x != -sqrt((-x)^2)（仮定 x<0 が効いている）" % len(POSS))

# ついでに: x>0 では x = +sqrt(x^2) であること
for x in POSS:
    rhs = sqrt_nonneg_bisect(x**_sage_const_2 )
    denom = max(RF(_sage_const_1 ), abs(x))
    rep.close(float(x / denom), float(rhs / denom), "x>0: x = sqrt(x^2) @x=%s" % x)

rep.finish()

